{
"predictors": 
[
  {
    "name": "Employee Satisfaction",
    "construction": "Survey data on employee satisfaction from firms, averaged over the past year.",
    "rationale": "Firms with satisfied employees are likely to have better corporate culture and higher productivity, potentially leading to better financial performance.",
    "higher_returns_for": "Firms with high employee satisfaction scores"
  },
  {
    "name": "Customer Loyalty",
    "construction": "Consumer survey data on brand loyalty, averaged over the last quarter.",
    "rationale": "Companies with loyal customers are likely to have stable, recurring revenue streams, leading to predictable earnings and potentially higher returns.",
    "higher_returns_for": "Firms with high customer loyalty scores"
  },
  {
    "name": "Diversity Score",
    "construction": "Measure of diversity in firms' executive teams and board of directors.",
    "rationale": "Increased diversity may lead to a broader range of perspectives and better decision making, enhancing firm value.",
    "higher_returns_for": "Firms with high diversity scores"
  },
  {
    "name": "Environmental Impact",
    "construction": "Measure of firms' environmental footprint, including waste generation and carbon emissions.",
    "rationale": "Firms that manage their environmental impact may be better at managing other risks, leading to higher returns.",
    "higher_returns_for": "Firms with lower environmental impact scores"
  },
  {
    "name": "R&D Intensity",
    "construction": "Ratio of research and development expenditures to total sales, averaged over the past five years.",
    "rationale": "Investments in R&D may lead to future innovations and competitive advantages, potentially leading to higher future returns.",
    "higher_returns_for": "Firms with high R&D intensity"
  },
  {
    "name": "Patent Count",
    "construction": "Number of patents granted to a firm over the past year.",
    "rationale": "Patents may provide a firm with a competitive advantage, leading to higher returns.",
    "higher_returns_for": "Firms with a high patent count"
  },
  {
    "name": "Product Quality",
    "construction": "Consumer survey data on perceived product quality, averaged over the last quarter.",
    "rationale": "High product quality may indicate a strong brand and pricing power, leading to higher returns.",
    "higher_returns_for": "Firms with high product quality scores"
  },
  {
    "name": "Cybersecurity Investment",
    "construction": "Measure of a firm's investment in cybersecurity infrastructure, relative to its industry peers.",
    "rationale": "Given the increasing importance of data, firms that invest in cybersecurity may be better positioned to protect their assets and reputation, leading to higher returns.",
    "higher_returns_for": "Firms with higher relative cybersecurity investment"
  },
  {
    "name": "CEO Tenure",
    "construction": "The number of years the current CEO has held the position.",
    "rationale": "Long-serving CEOs may suggest stability and consistent leadership, which may be associated with better financial performance and higher returns.",
    "higher_returns_for": "Firms with longer-serving CEOs"
  },
  {
    "name": "Corporate Philanthropy",
    "construction": "Measure of a firm's charitable donations as a percentage of its pre-tax profits.",
    "rationale": "Firms that engage in philanthropy may benefit from improved public image and employee morale, potentially leading to higher returns.",
    "higher_returns_for": "Firms with higher levels of corporate philanthropy"
  }
]
}
